-- Ticket 06 - Crimson Sky playable. Drop tables for the 16 v84 mobs the ticket adds.
--
-- Additive only: this file adds rows, it does not touch 152-drop-data.sql. That file is
-- a Liquibase changeSet (db/changelog-data.xml id=152), so editing it in place would
-- fail checksum validation on every database that has already run it.
--
-- No rate, quantity or questid below was invented. Every row is a verbatim copy of a
-- drop row that already exists in 152-drop-data.sql for the closest live Leafre mob,
-- with only the dropperid replaced. Analogues, by name identity first and level/HP
-- second (mob names read from the live client String.wz/Mob.img):
--
--   8300000 Soaring Hawk         <- 8190003 Skelegon              54 rows  (no name analogue, nearest live Leafre mob by level, both Lv.110)
--   8300001 Soaring Eagle        <- 8190004 Skelosaurus           52 rows  (no name analogue, nearest live Leafre mob by level, 110 vs 113)
--   8300002 Soaring Red Wyvern   <- 8150300 Red Wyvern            45 rows  (name analogue)
--   8300003 Soaring Blue Wyvern  <- 8150301 Blue Wyvern           40 rows  (name analogue)
--   8300004 Soaring Black Wyvern <- 8150302 Dark Wyvern           51 rows  (name analogue)
--   8300005 Soaring Griffey      <- 8180001 Griffey               75 rows  (name analogue, identical maxHP 3.7M)
--   8300006 Dragonica            <- 8180000 Manon                 63 rows  (no name analogue, the other live Leafre boss, 7 quest-gated row(s) NOT copied)
--   9500374 Green Cornian        <- 8150200 Green Cornian         36 rows  (name analogue, identical exp 3000)
--   9500375 Dark Cornian         <- 8150201 Dark Cornian          49 rows  (name analogue, identical exp 3700)
--   9500376 Jr. Newtie           <- 8190000 Jr. Newtie            44 rows  (name analogue, identical exp 3800)
--   9500377 Nest Golem           <- 8190002 Nest Golem            39 rows  (name analogue)
--   9500378 Blue Dragon Turtle   <- 8140700 Blue Dragon Turtle    32 rows  (name analogue, identical exp 1780)
--   9500379 Red Dragon Turtle    <- 8140701 Red Dragon Turtle     27 rows  (name analogue, identical exp 2100)
--   9500380 Skelegon             <- 8190003 Skelegon              54 rows  (name analogue, identical exp 4500)
--   9500381 Skelosaurus          <- 8190004 Skelosaurus           52 rows  (name analogue, identical exp 4750)
--   9500382 Leviathan            <- 8180000 Manon                 63 rows  (no name analogue, nearest live boss, Lv.105 vs 120, 7 quest-gated row(s) NOT copied)
--
-- A row with a non-zero questid is copied only from a NAME-MATCHED analogue. A clone of
-- Skelegon counting toward a Skelegon quest is right, but making the Manon boss quests
-- completable on Dragonica and Leviathan is a design change nobody asked for. That rule
-- drops 14 rows, 7 each from 8300006 and 9500382.
--
-- Comment lines here deliberately contain no statement terminator and no apostrophe. The
-- Liquibase changeSet runs with stripComments off and splitStatements on, so this header
-- reaches the driver
-- as part of the statement text. V84CrimsonSkyNodeTest asserts both.
--
-- 8300007 (Dragon Rider) gets no table: no map in scope places it and no v84 mob-skill
-- summon list names it, so nothing can kill it. Add one when a spawner exists.
-- 776 rows total.

INSERT INTO drop_data (dropperid, itemid, minimum_quantity, maximum_quantity, questid, chance)
